import numpy as np

rows, cols = 19, 19

# Define anti-diagonals for each band (r+c = constant)
bands = {
    8: 9,
    9: 19,
    6: 25,
    4: (27, 29),  # two anti-diagonals, alternating
    2: 35
}

solution = np.zeros((rows, cols), dtype=int)

def fill_diagonal(color, anti_diag):
    """Fill all cells where r+c = anti_diag with the given color"""
    for r in range(rows):
        c = anti_diag - r
        if 0 <= c < cols:
            solution[r, c] = color

def fill_band_4():
    """Band 4 fills two anti-diagonals c+r=27 and c+r=29, going down-right"""
    # Starting from row 9, alternating: (9,18) has 4, (10,17) has 4, (11,18) has 4, (12,17) has 4, etc.
    # Pattern: 4 appears at anti-diagonals (sums): 27, 29, 27, 29, ...
    # Also, secondary 4 from position (8,18) 
    for r in range(rows):
        for c in range(cols):
            if r + c in (27, 29):
                solution[r, c] = 4

# Fill all bands
for color in [8, 9, 6, 2]:
    if color in bands:
        fill_diagonal(color, bands[color])

# Fill band 4 specially
fill_band_4()

output = solution.tolist()
for row in output:
    print(row)

result = {"action": "submit", "grid": output}
print("\nSubmitting:", result)
